from collections import deque

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def main():
    s = input().strip()
    if not s:
        return

    tokens = s.split()
    nodes = {}

    for i in range(0, len(tokens), 3):
        if i + 2 >= len(tokens):
            break
        val = int(tokens[i])
        parent_val = int(tokens[i + 1])
        direction = tokens[i + 2]

        if val not in nodes:
            nodes[val] = Node(val)
        if parent_val not in nodes:
            nodes[parent_val] = Node(parent_val)

        if direction == 'L':
            nodes[parent_val].left = nodes[val]
        else:
            nodes[parent_val].right = nodes[val]

    if not nodes:
        return

    root = None
    all_children = set()

    for i in range(0, len(tokens), 3):
        if i + 2 < len(tokens):
            all_children.add(int(tokens[i]))

    for val in nodes:
        if val not in all_children:
            root = nodes[val]
            break

    if not root:
        return

    result = []
    queue = deque([root])

    while queue:
        node = queue.popleft()
        result.append(str(node.val))
        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)

    print(' '.join(result))

if __name__ == "__main__":
    main()
